window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/linguagens_2025.js"]=[{"title":"Apropriação cultural: identificar o propósito global","steps":["Leia o comando: ele pede a finalidade do texto sobre Halloween, não apenas um acontecimento mencionado. A repetição de exemplos deve orientar a síntese.","Localize a crítica: as lojas vendem fantasias que usam marcas indígenas e pessoas continuam a usá-las apesar do debate sobre racismo e cultural appropriation. O exemplo da fantasia com bala na testa intensifica o caráter ofensivo.","A declaração final contrasta aproveitar aspectos de cultura, raça e religião com ignorar as pessoas que vivem essa identidade. Portanto, o objetivo central é criticar o uso exploratório e desrespeitoso desses elementos: D."],"alternatives":{"A":"O episódio ofensivo menciona uma fantasia com uma bala na testa, não uma investigação sobre violência efetivamente praticada contra crianças. A alternativa transforma um exemplo de representação desrespeitosa em outro tema.","B":"As fantasias de Halloween são criticadas justamente por apropriarem elementos identitários. O texto não descreve como povos indígenas realizam suas próprias celebrações tradicionais.","C":"Não há elogio central às roupas ou apresentação de suas qualidades. O foco está no uso indevido por pessoas externas à cultura, e não numa valorização descritiva das vestimentas.","D":"A expressão cultural appropriation e a fala de Ames sustentam a crítica à retirada de elementos da identidade para benefício alheio, acompanhada de desconsideração pelos povos que os vivem.","E":"O relato de denúncia à plataforma é uma ação específica, mas o texto não se organiza como orientação ou lista de medidas de combate ao preconceito. Essa opção desloca o propósito de criticar para recomendar."},"takeaway":"Para reconhecer propósito, reúna exemplos e conclusão numa mesma ideia. Uma ação narrada pode ser evidência sem constituir a finalidade principal do texto.","key":"linguagens:L487","area":"linguagens","year":2025,"number":1,"answer":"D","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Snowflake generation e a dificuldade de lidar com frustrações","steps":["Identifique o uso figurado: snowflake não descreve clima. O próprio texto explica a expressão ao caracterizar estudantes como tão delicados que não lidam com ideias controversas nas aulas.","Relacione essa explicação à crítica de prometer uma vida sempre maravilhosa. Para o autor, alimentar o ego dessa maneira não prepara para fracasso ou catástrofe.","O fechamento contrapõe elogio indiscriminado e fortalecimento da resiliência. A expressão aponta uma juventude avessa a contrariedades, como resume E, sem que isso seja um diagnóstico científico de toda uma geração."],"alternatives":{"A":"O texto não centra a expressão em obstáculos externos impostos pela universidade. A caracterização recai sobre a reação dos estudantes a controvérsias e frustrações.","B":"As mensagens de incentivo aparecem como parte da crítica, não como o sentido principal da expressão. Snowflake generation caracteriza a fragilidade atribuída à juventude, e não as mensagens em si.","C":"Há referência a enfrentar catástrofes, mas a expressão não funciona como instrução para agir numa emergência. Ela integra a avaliação crítica de uma postura diante de adversidades.","D":"O ambiente universitário situa o exemplo, mas não há descrição central de conflitos entre pessoas ou grupos. O traço destacado é não suportar ideias controversas e contrariedades.","E":"A explicação so delicate they can’t handle controversial ideas e o contraste com resiliência sustentam a leitura de resistência a frustrações e contrariedades."},"takeaway":"Expressões figuradas em inglês costumam ser esclarecidas pelo contexto imediato. Procure a caracterização que vem depois e a relação com a conclusão, sem traduzir palavra por palavra.","key":"linguagens:L490","area":"linguagens","year":2025,"number":4,"answer":"E","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Humor e privação de sono","steps":["Compare os copos: quem dormiu de 8 a 10 horas recebe o menor; de 5 a 7, o intermediário; o maior pergunta “What is sleep?”.","A pergunta significa “O que é sono?” e funciona como exagero bem-humorado: a pessoa teria dormido tão pouco que nem reconheceria o que é dormir.","A relação é com escassez de sono, A. O texto não afirma dependência nem anuncia um produto para provocar sono."],"alternatives":{"A":"O exagero associa o maior copo a quem teve poucas ou nenhuma hora de sono, dentro da escala da imagem.","B":"A imagem não orienta uma rotina de descanso; usa as horas já dormidas para brincar com o tamanho dos copos.","C":"Não há preço nem gasto comparativo. Além disso, combater a insônia não é a função sugerida para a bebida.","D":"Embora bebidas possam conter cafeína, a imagem não discute dependência; isso extrapola a informação disponível.","E":"O copo maior sugere manter-se desperto após dormir pouco, e não consumir um produto que induza o sono."},"takeaway":"Em texto multimodal, compare inscrições e tamanhos; traduza a pergunta pelo efeito de humor, não só literalmente.","key":"linguagens:L491","area":"linguagens","year":2025,"number":5,"answer":"A","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Bilhetes: reconhecer a diversidade dos usos cotidianos","steps":["O comando restringe a leitura ao gênero bilhete. Localize os trechos em que a autora explica onde e por que usa sua letra, em vez de escolher uma afirmação geral sobre tecnologia.","Na cozinha e na geladeira, os bilhetes comunicam tarefas aos coabitantes. No escritório, post-its permitem comunicar-se consigo mesma e lembrar o que precisa fazer.","A autora descreve destinatários, lugares e funções diferentes. Mesmo concisos e efêmeros, os bilhetes permanecem úteis. A síntese correta é diversidade de usos no cotidiano: E."],"alternatives":{"A":"A comunicação é doméstica e pessoal, com lembretes e garranchos. Não há destaque à formalidade como característica central dos bilhetes usados com pessoas próximas.","B":"A ansiedade é mencionada no fluxo de tarefas da vida adulta. Isso não equivale a fazer da crítica à velocidade da comunicação o eixo da descrição do gênero bilhete.","C":"A autora diz ser lacônica consigo mesma, às vezes a ponto de não se entender depois. Trata-se de sua prática, não da imposição de uma regra obrigatória de concisão para toda anotação.","D":"O texto mostra que a escrita manual permanece em situações específicas, inclusive nos bilhetes. Não organiza essa passagem como contestação da prática de escrever à mão.","E":"A variedade aparece nos espaços, destinatários e finalidades: comunicar-se com moradores da casa, lembrar tarefas e dirigir mensagens a si própria. É o conjunto que o comando pede reconhecer."},"takeaway":"Quando o comando recorta um gênero, compare suas situações de uso. Uma característica particular de um exemplo não deve ser transformada numa regra universal do gênero.","key":"linguagens:L719","area":"linguagens","year":2025,"number":6,"answer":"E","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Crônica: do episódio pessoal à reflexão","steps":["O pedido é reconhecer o traço que caracteriza o gênero crônica, não apenas um tema ou recurso que também poderia aparecer em outros gêneros.","A autora começa pela estranheza com de próprio punho, relata uma situação bancária, observa sua caligrafia e descreve bilhetes de casa e do escritório. São fatos de sua experiência cotidiana.","Esses episódios sustentam reflexão mais ampla sobre formas de escrita e coexistência de tecnologias. Essa passagem do pessoal à reflexão caracteriza o texto: C."],"alternatives":{"A":"Há opinião sobre um tema coletivo, mas isso também caracteriza artigos e outros textos argumentativos. A opção não contempla o modo específico de chegar à reflexão a partir da experiência pessoal cotidiana.","B":"Tecnologias de escrita são o tema, não a característica distintiva do gênero. Uma exposição técnica poderia tratar do mesmo assunto sem constituir crônica.","C":"O texto transforma experiências pessoais, como a situação no banco e os bilhetes domésticos, em reflexão sobre a escrita. A combinação de cotidiano e elaboração reflexiva responde ao comando.","D":"A interlocução com o leitor pode ocorrer, mas não distingue sozinha a crônica. Perguntas e aproximação discursiva também aparecem em publicidade, cartas e artigos.","E":"A sequência não se limita a narrar fatos numa ordem temporal contínua. Há digressões, avaliações e exemplos que organizam a reflexão; cronologia por si só não define crônica."},"takeaway":"Para identificar gênero, relacione situação, organização e finalidade. Tema e recurso isolado podem aparecer em muitos gêneros e não bastam para diferenciá-los.","key":"linguagens:L331","area":"linguagens","year":2025,"number":7,"answer":"C","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Caligrafia pessoal e fontes tipográficas digitais","steps":["O comando solicita o elemento usado no texto para ilustrar a escrita digital em contraste com a letra manuscrita. Não pede qualquer característica possível de dispositivos eletrônicos.","A autora observa que suas mãos continuam no teclado e nas telas, mas já não expressam sua letra. Em seu lugar aparecem Times New Roman, Arial, Calibri e muitas outras opções.","Esses nomes são fontes tipográficas. A diversidade delas ilustra diretamente a escrita digital na comparação proposta, correspondendo a D."],"alternatives":{"A":"Lápis, caneta, giz e outros meios também são tecnologias e aparecem associados à escrita manual. Diversidade de tecnologias é ampla demais para identificar o exemplo específico da escrita digital.","B":"O texto não faz dessa passagem uma explicação sobre desenvolver novos recursos. Ele mostra opções tipográficas já disponíveis ao usuário.","C":"Telas são mencionadas, mas a comparação solicitada recai sobre a aparência da letra: caligrafia pessoal versus fontes. Interações mediadas por telas não nomeiam esse contraste com precisão.","D":"Times New Roman, Arial e Calibri exemplificam fontes que substituem a marca pessoal da caligrafia na apresentação digital do texto. É a referência explicitamente usada pela autora.","E":"A delimitação de espaços aparece na discussão de onde a autora ainda usa sua letra. Não é o recurso que ilustra a escrita digital no contraste entre as formas da letra."},"takeaway":"Responda ao recorte exato do comando. Uma característica verdadeira da tecnologia pode ser distratora quando o texto usa outro exemplo para construir a comparação.","key":"linguagens:L720","area":"linguagens","year":2025,"number":8,"answer":"D","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Conclusão: tecnologias de escrita coexistem","steps":["A pergunta pede a conclusão da autora. Dê peso especial ao parágrafo final e verifique como ele reúne os exemplos anteriores, em vez de selecionar uma vantagem genérica da tecnologia.","O texto afirma que nada dispensa nada dependendo da tarefa e rejeita pensar tudo como excludente. Bilhetes, post-its e documentos digitais continuam presentes em situações diferentes.","A mudança de do punho ao pixel para o punho e o pixel sintetiza coexistência, não substituição integral. A alternativa C expressa essa conclusão."],"alternatives":{"A":"Facilitar a vida pode parecer uma ideia plausível sobre inovação, mas não resume a conclusão específica. A autora enfatiza funções e coexistência, não uma evolução linear para a facilidade.","B":"O texto reconhece diferenças de acesso, mas não conclui que as novas tecnologias atingem todas ou diferentes realidades de modo garantido. Esse não é o argumento que reúne os exemplos finais.","C":"A autora mantém práticas manuscritas e digitais segundo suas funções e substitui a ideia de passagem exclusiva por uma associação. Isso sustenta diretamente a coexistência.","D":"Agilidade pode ser associada ao digital, mas não é a tese final defendida. O texto destaca que o manuscrito segue útil e não organiza a conclusão como comparação de velocidade.","E":"O texto não estabelece uma regra de que cada tecnologia nasce exatamente onde é necessária. Ele descreve reposicionamento de usos e funções de recursos já existentes."},"takeaway":"Para achar uma conclusão, identifique o enunciado que integra os exemplos e a formulação final. Não confunda tese com uma afirmação genericamente plausível sobre o tema.","key":"linguagens:L782","area":"linguagens","year":2025,"number":9,"answer":"C","subject":"Tecnologias da Informação e Comunicação","topic":"Tecnologias, comunicação e transformações sociais","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"De uma passagem a uma soma: o valor de “e”","steps":["O comando pergunta qual recurso marca a síntese da opinião. Procure a formulação que condensa o argumento desenvolvido, não qualquer ocorrência de primeira pessoa.","Do punho ao pixel sugere um percurso de uma forma a outra, compatível com uma leitura de substituição. A autora recusa essa formulação e propõe o punho e o pixel.","A coordenação com e associa as formas e resume a coexistência mostrada pelos exemplos. A substituição entre expressões é, portanto, o recurso solicitado: E."],"alternatives":{"A":"A primeira pessoa apresenta a experiência inicial e a voz da narradora, mas não condensa a conclusão sobre a relação entre tecnologias de escrita.","B":"Na verdade retifica ou esclarece a interpretação da situação bancária. Seu papel é local, distinto da síntese final sobre coexistência de práticas.","C":"Minha marca a relação da autora com sua caligrafia. O possessivo não expressa, por si, a tese sobre a convivência entre escrita manual e digital.","D":"Comigo mesma retoma a autora como destinatária de suas anotações e observações. Essa autorreferência não sintetiza a relação geral entre os modos de escrever.","E":"A troca de uma expressão de percurso por uma associação com e transforma a imagem de substituição em coexistência. É a formulação final que resume a opinião defendida."},"takeaway":"Recursos gramaticais produzem relações de sentido. Compare a interpretação das duas construções e relacione a mudança à tese, em vez de apenas nomear a classe de uma palavra.","key":"linguagens:L332","area":"linguagens","year":2025,"number":10,"answer":"E","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Inocência: a jovem descrita, os homens decidindo","steps":["Observe quem fala e decide: Pereira descreve a aparência e o comportamento da filha, enquanto relata a Cirino que tratou de seu casamento. A voz da jovem não participa da decisão nesse fragmento.","O pai apresenta qualidades e recursos do pretendente e afirma que os pais devem tomar o assunto para si. Cirino aprova. O protagonismo da negociação fica entre figuras masculinas.","Assim, o contraste relevante é a mulher como figura descrita e destinada ao arranjo, diante da agência masculina. Isso corresponde a B. A interpretação se refere ao trecho e ao discurso das personagens, não prova uma posição única de toda a literatura romântica."],"alternatives":{"A":"O ambiente rural é mencionado, mas o pai compara a filha a uma moça de cidade e não sustenta que o campo foi responsável por sua formação moral. A opção desloca o foco da relação de poder para uma valorização do espaço.","B":"A filha é caracterizada por beleza e modos, enquanto pai e pretendente ocupam o espaço da decisão matrimonial, com aprovação de Cirino. A assimetria sustenta a figura decorativa diante do protagonismo masculino.","C":"O trecho elogia o pretendente e seus possíveis recursos, mas não estabelece equivalência de origem social como condição de harmonia. A decisão não é apresentada como acordo entre os próprios jovens.","D":"Há referência ao dinheiro que o pretendente teria acumulado, não a um dote exigido da família da noiva como condição. Confundir esses recursos altera a informação do texto.","E":"A jovem é descrita e o casamento é discutido de forma direta. O problema não é um enigma sobre sua identidade, mas sua posição diante das decisões masculinas."},"takeaway":"Em textos literários, observe distribuição de voz e ação: quem é descrito e quem decide. Uma paisagem ou detalhe econômico pode aparecer sem ser o eixo solicitado pelo comando.","key":"linguagens:L470","area":"linguagens","year":2025,"number":11,"answer":"B","subject":"Literatura","topic":"Romantismo","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Parasurf: política pública como instrumento de inclusão","steps":["Localize o agente e a finalidade: o Ministério do Esporte lança um programa para ampliar oportunidades de prática do surf por pessoas com deficiência.","O texto explica a adaptação da modalidade e afirma que a iniciativa pretende promover inclusão, igualdade e respeito. Não apresenta uma pesquisa de resultados nem comparação de investimentos.","A síntese é a importância de uma política pública esportiva para a inclusão. A alternativa C preserva tanto o instrumento institucional quanto o objetivo central."],"alternatives":{"A":"O programa descrito é brasileiro e não há informação sobre adesão de diferentes países. A referência aos Jogos de Paris não demonstra participação internacional no programa.","B":"O ano paralímpico situa o lançamento, mas a finalidade é ampliar oportunidades de prática em diferentes categorias e manifestações. Reduzir o foco a atender demandas paralímpicas restringe o alcance apresentado.","C":"O lançamento por um órgão público e a finalidade explícita de ampliar oportunidades e inclusão sustentam a relação entre política esportiva e participação social.","D":"O texto apresenta objetivos da iniciativa, não dados que comprovem sua eficiência em megaeventos. Transformar uma intenção declarada em resultado medido extrapola a fonte.","E":"Não há levantamento de escassez de recursos para práticas de aventura. Essa hipótese pode ser discutida em outro contexto, mas não constitui a informação evidenciada pelo texto."},"takeaway":"Diferencie objetivo de resultado comprovado. A criação de uma política pode evidenciar sua finalidade sem demonstrar, sozinha, eficiência, alcance internacional ou diagnóstico orçamentário.","key":"linguagens:L696","area":"linguagens","year":2025,"number":12,"answer":"C","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Norma-padrão e convenções do gênero legal","steps":["Identifique o gênero: o fragmento tem artigo, parágrafos, referência ao caput e formulação de obrigatoriedade. São marcas de um texto de lei.","A linguagem formal e a organização normativa se relacionam à função institucional de estabelecer regras com alcance definido. A pergunta é por que esse registro é adequado, não por que o tema é importante.","As características do gênero legal justificam o emprego da norma-padrão: E. A resposta não estabelece superioridade linguística de grupos nem restringe a lei a especialistas."],"alternatives":{"A":"A lei não se dirige apenas a um público especializado. Seu alcance envolve instituições de ensino e a sociedade; a formalidade decorre da convenção institucional, não de uma exigência de especialização de todos os leitores.","B":"A relevância cultural do conteúdo não exige, por si, norma-padrão: o mesmo tema pode aparecer em conversa, canção e outros registros. A justificativa solicitada está no gênero.","C":"O conteúdo envolve escolas, mas o fragmento circula como dispositivo legal, não apenas material pedagógico. Contexto de educação não explica sozinho suas convenções normativas.","D":"A importância para grupos étnico-raciais é parte do conteúdo e de seus efeitos sociais, não uma razão linguística que imponha esse registro a qualquer texto sobre eles.","E":"Artigo, parágrafos, obrigação e referência ao caput configuram um texto legal. O registro formal é adequado às convenções e à função institucional desse gênero."},"takeaway":"Adequação de registro depende de gênero, finalidade e situação. Não confunda relevância do tema com a razão específica para escolher uma forma de linguagem.","key":"linguagens:L260","area":"linguagens","year":2025,"number":13,"answer":"E","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf"}},{"title":"Entrar Fernando e sair Pessoa","steps":["O cartaz divide o nome Fernando Pessoa entre duas frases e anuncia que todo mundo sai melhor do que entrou.","O jogo associa participar do evento e ler a tornar-se uma pessoa transformada. As imagens de histórias e lugares ampliam essa ideia.","O argumento central ressalta o impacto da leitura na vida: C. O escritor é uma referência para construir esse sentido, não o único objeto anunciado."],"alternatives":{"A":"Fernando Pessoa fornece o trocadilho, mas a mensagem promove a experiência de leitura, não apenas a divulgação de sua obra.","B":"O evento é anunciado, porém o argumento específico da combinação verbal e visual é a transformação do leitor.","C":"O jogo com o nome e a frase sobre sair melhor apresentam a leitura como experiência transformadora.","D":"As referências a lugares não convertem a mensagem em propaganda de turismo cultural na cidade.","E":"O cartaz não demonstra uma influência histórica de Pessoa sobre autores brasileiros; essa relação não é desenvolvida."},"takeaway":"Distinga aquilo que um anúncio divulga do argumento usado para persuadir o público.","key":"linguagens:L001","area":"linguagens","year":2025,"number":14,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Recursos expressivos e construção de sentidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Retrato como afirmação de identidade","steps":["O texto explica que o retrato ocidental privilegiou elites e deixou pessoas negras e indígenas invisibilizadas ou sem identificação.","Dalton Paula pinta e nomeia Zeferina e João de Deus Nascimento, dando visibilidade a sujeitos historicamente marginalizados.","A arte atua, assim, na afirmação da identidade social: A. Não se demonstra ascensão econômica dos retratados nem venda de retratos às periferias."],"alternatives":{"A":"Representar e identificar essas pessoas confronta a invisibilidade e amplia o reconhecimento de identidades sociais.","B":"O texto trata de protagonismo na representação, não de comunidades adquirindo quadros ou um gênero de pintura.","C":"Não se afirma que duas personagens simbolizem integralmente toda a sociedade brasileira; o foco é o reconhecimento.","D":"Visibilidade simbólica na pintura não prova mudança de posição econômica ou ascensão social dos indivíduos.","E":"A referência não está centrada em lembranças afetivas tradicionais, mas na crítica à exclusão histórica da representação."},"takeaway":"Representação artística também produz memória e reconhecimento; não reduza seus efeitos à função decorativa.","key":"linguagens:L614","area":"linguagens","year":2025,"number":15,"answer":"A","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Símbolos do conflito amoroso","steps":["O próprio poema estabelece as correspondências: “tu és dúbio mar” e “Eu sou [...] rocha”.","O mar avança e recua, enquanto a rocha permanece imóvel. A paisagem representa a tensão entre os sujeitos e seus sentimentos.","Essa transposição simbólica do conflito para imagens naturais sustenta E, em vez de uma descrição apenas literal do litoral."],"alternatives":{"A":"O eu lírico não rejeita as emoções: explicita amor, mágoa e dor ao desenvolver a relação.","B":"A dubiedade é uma característica do outro, mas a resposta mais completa explica o mecanismo simbólico mar–rocha.","C":"Apenas o mar é associado à oscilação; a rocha representa imobilidade, não dois sujeitos igualmente volúveis.","D":"A inconsciência é atribuída ao “tu” comparado ao mar, e não ao eu lírico que se identifica com a rocha.","E":"As imagens de mar e rocha metaforizam o conflito amoroso e dão expressão indireta à experiência interior."},"takeaway":"Procure no poema as equivalências entre paisagem e subjetividade antes de aplicar um rótulo de escola literária.","key":"linguagens:L474","area":"linguagens","year":2025,"number":16,"answer":"E","subject":"Literatura","topic":"Outras escolas e tradições literárias","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Memória e presente ressignificado","steps":["A repetição de “antes de” recupera vários aspectos da vida da avó: trabalho, mudanças, filhos, histórias e gestos de cuidado.","O desfecho revela o Alzheimer e contrapõe “eu era sua neta” à permanência afetiva de “sempre será minha avó”.","Os fatos anteriores mudam o modo de compreender o presente da relação, sustentando C. Não formam uma lista de ações rigorosamente consecutivas."],"alternatives":{"A":"“Antes de” expressa anterioridade; não organiza os acontecimentos como simultâneos.","B":"O objetivo não é comparar lembranças entre si, mas articulá-las à situação atual e ao vínculo afetivo.","C":"O passado recuperado dá novo sentido ao presente marcado pela doença, sem apagar a relação entre avó e neta.","D":"As retomadas não constituem uma cronologia linear de ações consecutivas; o texto atravessa diferentes momentos.","E":"A locução marca o recuo temporal e a progressão afetiva, não uma explicação causal para o surgimento das memórias."},"takeaway":"Uma expressão temporal pode estruturar um contraste afetivo, não apenas ordenar eventos no calendário.","key":"linguagens:L333","area":"linguagens","year":2025,"number":17,"answer":"C","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O espetáculo esportivo e o que ele oculta","steps":["A ex-atleta contrapõe as imagens de conquista às rotinas longas de treinamento, limites e dificuldades humanas.","O texto critica uma representação midiática que faz o sucesso parecer mais fácil e inclusivo do que é.","A conclusão é que os meios de comunicação invisibilizam dificuldades do esporte: A. A crítica não declara que todo treinamento de alto nível seja desestimulante."],"alternatives":{"A":"A mídia mostra conquistas e motivação, deixando menos visíveis as condições duras que a entrevistada descreve.","B":"A entrevistada aponta esforço e limites, mas não generaliza o treinamento como experiência necessariamente desestimulante.","C":"O problema é a imagem pública incompleta, não uma afirmação de que o trabalho contínuo não tenha valor profissional.","D":"O texto não analisa políticas de financiamento de atletas jovens; inserir essa causa extrapola o argumento.","E":"Não se discutem rótulos de iniciantes, e sim a apresentação espetacularizada de trajetórias bem-sucedidas."},"takeaway":"Identifique quem é criticado e por qual representação; dificuldades reais não equivalem a condenar a prática esportiva.","key":"linguagens:L654","area":"linguagens","year":2025,"number":18,"answer":"A","subject":"Educação Física","topic":"Esporte, inclusão e práticas corporais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Saúde emocional no desempenho esportivo","steps":["As atletas destacam terapia, apoio psicológico e controle da própria cabeça durante o treinamento e as apresentações.","A fala de Rebeca desloca o foco de derrotar outra atleta para lidar com desafios internos.","O ponto comum é a importância da saúde emocional: E. Não há defesa de abandonar ou subordinar todo o treino físico ao mental."],"alternatives":{"A":"Equipamentos não são o foco das falas: elas ressaltam acompanhamento psicológico e autorregulação.","B":"Valorizar o aspecto mental não significa torná-lo hierarquicamente superior ao físico; a alternativa exagera.","C":"A fala citada relativiza justamente a centralidade da adversária e destaca o enfrentamento dos próprios desafios.","D":"A expressão corporal pode integrar a prática, mas não é o assunto comum das entrevistas apresentadas.","E":"As referências à terapia e ao suporte psicológico convergem para a importância da saúde emocional das atletas."},"takeaway":"Reconheça a ideia compartilhada pelos exemplos, evitando transformar valorização em exclusividade ou hierarquia.","key":"linguagens:L671","area":"linguagens","year":2025,"number":19,"answer":"E","subject":"Educação Física","topic":"Corpo, saúde e qualidade de vida","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Memória africana no patrimônio linguístico","steps":["O texto descreve um repertório ritual com aparência portuguesa e sistemas lexicais de diferentes línguas africanas.","Essa presença preserva marcas históricas das línguas faladas por pessoas escravizadas no Brasil, em práticas culturais transmitidas.","A contribuição patrimonial está na conservação desses elementos: B. O texto diferencia tal herança das nações africanas políticas atuais."],"alternatives":{"A":"A dimensão mítica existe, mas não é a explicação específica da importância para o patrimônio linguístico nacional.","B":"A língua ritual conserva elementos de falares africanos trazidos por pessoas escravizadas e transmitidos culturalmente.","C":"A aparência portuguesa não significa que a contribuição central seja resgatar expressões portuguesas coloniais.","D":"O repertório participa de ritos, porém o comando pede sua importância linguística histórica, não decifrar cerimônias.","E":"O texto ressalta heranças históricas diversas e não afirma equivalência com o léxico africano contemporâneo."},"takeaway":"Patrimônio linguístico inclui memória de contatos culturais e de grupos historicamente silenciados.","key":"linguagens:L261","area":"linguagens","year":2025,"number":20,"answer":"B","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ver novas formas na matéria-prima","steps":["O depoimento descreve troncos e galhos que passam a ser percebidos como bancos, animais ou bailarinas.","A imagem mostra gravetos transformados em figuras: o material recebe novos sentidos e usos por meio da criação artística.","A originalidade está na ressignificação da matéria-prima: B. O texto não fundamenta produção industrial seriada nem a imitação de modelos canônicos."],"alternatives":{"A":"Reaproveitar madeira pode ter efeitos ambientais, mas o foco é a percepção e transformação criativa, não uma política de redução de impacto.","B":"Os artistas atribuem aos galhos novas formas, sentidos e funções, como explicitado no depoimento e na fotografia.","C":"Não há indicação de cópia de modelos consagrados; enfatiza-se o olhar próprio sobre a madeira disponível.","D":"Os bailarinos são exemplos de formas criadas, mas não demonstram uma prática corporal específica da comunidade.","E":"A criação singular a partir de galhos não caracteriza replicação padronizada para distribuição em grande escala."},"takeaway":"Na arte com materiais cotidianos, observe a transformação de sentido, não apenas a origem do material.","key":"linguagens:L615","area":"linguagens","year":2025,"number":22,"answer":"B","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Feridas coloniais na azulejaria","steps":["A azulejaria remete a uma tradição visual de origem europeia, vinculada à história colonial brasileira.","A obra rompe a superfície e expõe uma aparência de carne viva. Os cortes e fissuras tornam visível uma violência sob essa tradição ornamental.","Essa associação crítica entre herança colonial e ferida sustenta C. A obra não é um registro literal de falta de conservação predial."],"alternatives":{"A":"Não se demonstra uma substituição triunfante da arte portuguesa pela brasileira; há problematização da herança colonial.","B":"O efeito de carne na azulejaria é um recurso crítico e híbrido, não simples manutenção da representação realista.","C":"A ruptura da superfície ornamental expõe simbolicamente violências associadas à formação colonial brasileira.","D":"O incentivo financeiro à produção artística não é o tema construído pelos cortes e pela carne representada.","E":"Interpretar a fissura como mera negligência arquitetônica perde a dimensão simbólica e histórica da obra."},"takeaway":"Relacione material, gesto visual e contexto histórico; uma ruína artística pode funcionar como crítica, não como documento de conservação.","key":"linguagens:L616","area":"linguagens","year":2025,"number":23,"answer":"C","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O futuro das crianças e o combate ao racismo","steps":["O cartaz mostra crianças negras e indígenas acompanhadas de projeções de futuro como médica ou advogado, com oportunidades pela frente.","As profissões não funcionam como teste vocacional, mas como imagem de potencial que o racismo pode impedir de se realizar.","A campanha busca sensibilizar a sociedade para os benefícios de uma infância sem racismo: B. A frase “enxergue a igualdade” confirma essa finalidade."],"alternatives":{"A":"A campanha inclui convite à participação, mas as projeções profissionais não se limitam a arrecadação nem apenas a povos originários.","B":"O futuro profissional imaginado torna concretos os ganhos de combater barreiras raciais às oportunidades das crianças.","C":"Não se orienta cada criança a escolher uma profissão; apresentam-se possibilidades de realização em igualdade.","D":"A educação aparece entre os direitos afetados, mas o objetivo específico é combater o racismo, não apenas ampliar educação infantil.","E":"A presença do Unicef identifica o emissor; a finalidade não é promover a agência, e sim mobilizar contra discriminação."},"takeaway":"Em campanhas, interprete o exemplo à luz do slogan e do problema social, não como uma recomendação literal isolada.","key":"linguagens:L045","area":"linguagens","year":2025,"number":24,"answer":"B","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Criticar clichês usando os próprios clichês","steps":["O cronista acumula expressões como “novo normal”, “zona de conforto”, “lugar de fala” e “fora da caixinha”.","Ele emprega de modo deliberado as fórmulas prontas que está criticando. A concentração produz humor e evidencia seu uso automatizado.","A estratégia central é o humor gerado pelo próprio material linguístico discutido: E. A presença de primeira pessoa, sozinha, não explica essa ironia."],"alternatives":{"A":"A efemeridade aparece na reflexão final, mas não explica a estratégia predominante de composição cômica.","B":"A primeira pessoa marca subjetividade, porém não identifica o recurso específico de reutilizar os clichês criticados.","C":"A repetição de “assim” é apenas parte do jogo; o humor se constrói ao longo de todo o texto com várias expressões.","D":"“Você” ajuda a interlocução, mas a crítica não se apoia principalmente numa estratégia de sedução direta.","E":"O texto encena a linguagem automatizada em vez de apenas descrevê-la, criando humor pela acumulação dos clichês."},"takeaway":"Pergunte como a crítica é construída: um texto pode fazer humor imitando o discurso que questiona.","key":"linguagens:L144","area":"linguagens","year":2025,"number":25,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Variação regional no vocabulário","steps":["O quadro associa nomes diferentes do doce a estados e regiões: curau, canjica, canjiquinha, papa de milho e outros.","As diferenças dizem respeito à denominação conforme o lugar de uso, inclusive com inversão de nomes entre certas regiões.","Trata-se de variação linguística regional, B. Não se estabelece uma disputa sobre qual estado prepara o melhor prato."],"alternatives":{"A":"Os nomes podem ter associações afetivas, mas o texto os distribui por localidades, sem analisar vínculos emocionais.","B":"Os diferentes nomes vinculados a regiões exemplificam variação geográfica ou diatópica do vocabulário.","C":"Não há classificação de qualidade nem competição entre regiões; a diversidade é o objeto da apresentação.","D":"O texto não ensina receitas ou compara procedimentos culinários; destaca nomenclaturas para alimentos.","E":"Não se comparam gostos dos consumidores, e sim diferentes usos de palavras no território brasileiro."},"takeaway":"Variação lexical regional não é erro: são denominações que dependem da comunidade e do lugar.","key":"linguagens:L185","area":"linguagens","year":2025,"number":26,"answer":"B","subject":"Variação linguística","topic":"Variedades linguísticas, identidade e preconceito","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Luta e enfrentamento dos próprios limites","steps":["O autor não reduz a diferença à presença de juízes ou medalhas: contrapõe desumanização e reconhecimento do outro.","Na luta, lidar com raiva, orgulho e frustração permite combater também as próprias limitações.","A superação pessoal é a distinção enfatizada: A. Considerar apenas o adversário como desafio externo ignora a conclusão do texto."],"alternatives":{"A":"A luta envolve o enfrentamento dos próprios limites e emoções, fundamento da dimensão de superação pessoal.","B":"A mera presença de violência não distingue os conceitos conforme o argumento; o texto destaca a relação com o outro e consigo.","C":"O texto não define a briga pelo predomínio de regras; a pergunta inicial justamente problematiza uma diferença apenas externa.","D":"O adversário existe, mas o argumento termina enfatizando o combate interno, não só o desafio externo.","E":"O desenvolvimento de habilidades é associado à luta, não apresentado como característica positiva definidora da briga."},"takeaway":"Na leitura argumentativa, a conclusão pode deslocar o foco do contraste inicial para uma dimensão menos evidente.","key":"linguagens:L655","area":"linguagens","year":2025,"number":27,"answer":"A","subject":"Educação Física","topic":"Esporte, inclusão e práticas corporais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O apelo para que o morto acorde","steps":["Observe a repetição dos imperativos: “acorda”, “recupera o alento” e “foge”. O eu lírico se dirige à criança morta como se ela pudesse reagir.","A morte é figurada como sono e o sepultamento como viagem da qual seria possível escapar.","O luto se intensifica pela recusa afetiva da irreversibilidade: B. O poema não precisa propor literalmente uma ressurreição religiosa."],"alternatives":{"A":"A paisagem contribui para a atmosfera, mas não explica tão diretamente a insistência em acordar e fugir.","B":"Os pedidos impossíveis de despertar revelam resistência emocional à morte definitiva e intensificam o sofrimento.","C":"A sonoridade existe, mas atribuí-la apenas à pontuação não explica a insistência semântica nos imperativos.","D":"Não se constrói uma consolação religiosa fortalecedora; predomina o apelo angustiado diante da perda.","E":"O sono é uma imagem da morte, não indicação de que a cena inteira seja um sonho do eu lírico."},"takeaway":"Interprete as ordens impossíveis como expressão de afeto e luto, sem exigir que sejam ações realizáveis.","key":"linguagens:L475","area":"linguagens","year":2025,"number":28,"answer":"B","subject":"Literatura","topic":"Outras escolas e tradições literárias","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Enumeração e reprodução de privilégios","steps":["A enumeração de produtos e estruturas do engenho aparece junto de reis, nobres e muitos escravizados, situando uma hierarquia.","O parágrafo seguinte mostra o círculo familiar conservando bens e posições, “sem deixar escapar” nada para os de fora.","A riqueza enumerada evidencia a permanência de privilégios de classe: A. A fartura não é apresentada como benefício distribuído a todos."],"alternatives":{"A":"A concentração de bens e sua transmissão dentro da mesma parentela mostram a reprodução dos privilégios.","B":"A lista não oferece um panorama demográfico da população rural; organiza uma crítica à concentração social.","C":"A abundância é acompanhada de escravidão e exclusão; não há celebração de benefícios agrícolas gerais.","D":"O narrador não defende um projeto de atividade coletiva; critica o fechamento dos benefícios num grupo familiar.","E":"A repetição de gerações evidencia a conservação dos domínios, não uma valorização moral do trabalho herdado."},"takeaway":"Uma enumeração ganha sentido pelo contexto: riqueza pode funcionar como denúncia de concentração, não como elogio.","key":"linguagens:L364","area":"linguagens","year":2025,"number":29,"answer":"A","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um verbete na perspectiva Wajãpi","steps":["O verbete explica o urucum por meio das relações com donos das plantas, espíritos, proteção e práticas cotidianas Wajãpi.","A definição incorpora uma perspectiva ancestral indígena, em vez de se limitar a propriedades botânicas ou farmacológicas.","Esse registro de palavras e concepções culturais contribui para o patrimônio linguístico: B. Não é um protocolo científico de uso medicinal."],"alternatives":{"A":"Os usos incluem proteção e vida cotidiana, e não apenas um rito medicinal isolado; a alternativa reduz o alcance do verbete.","B":"O termo é explicado a partir de saberes e relações culturais Wajãpi, preservando uma perspectiva ancestral indígena.","C":"A presença de nomes não estabelece equivalência entre vocábulos de várias línguas indígenas distintas.","D":"O texto registra e apresenta saberes tradicionais; não demonstra uma atualização ou substituição deles.","E":"A explicação não está baseada em ensaios científicos de propriedades farmacológicas das plantas."},"takeaway":"Registrar patrimônio linguístico envolve também o modo de significar o mundo, não apenas uma tradução de palavras.","key":"linguagens:L262","area":"linguagens","year":2025,"number":30,"answer":"B","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Os vários sentidos de rede","steps":["O poema contrapõe as redes digitais à rede de descanso pendurada na casa de um amigo, cercada de experiências sensoriais.","As perguntas sobre quem somos dentro e fora da tela ampliam a reflexão para a qualidade das relações e a experiência humana.","O jogo com “rede” evidencia o impacto da tecnologia nas interações: D. Há questionamento, não uma simples lista de funcionalidades digitais."],"alternatives":{"A":"Os meios digitais são ponto de partida, mas o contraste com encontros presenciais amplia o tema para os efeitos nas relações.","B":"Não se recomendam atualizações de aplicativos ou plataformas; atualização técnica não é o problema do poema.","C":"As perguntas sobre identidade participam da reflexão, mas não comprovam conflitos específicos de usuários.","D":"O contraste entre sensações e convivência fora da tela e a experiência digital problematiza suas repercussões nas interações.","E":"O desejo de convivência aparece, porém a oposição entre redes serve a uma reflexão mais ampla sobre mediação tecnológica."},"takeaway":"Polissemia pode estruturar uma comparação crítica entre modos de vida, além de produzir apenas um trocadilho.","key":"linguagens:L721","area":"linguagens","year":2025,"number":31,"answer":"D","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O suporte também condiciona o gênero","steps":["O texto discute a crônica no jornal e destaca a página compartilhada com várias matérias.","Essa limitação obriga o cronista a explorar economicamente um pequeno número de laudas, influenciando sua forma de escrever.","O aspecto tecnológico e material é a restrição espacial do suporte: E. Ideologia e público também aparecem, mas são outras dimensões da discussão."],"alternatives":{"A":"A conexão ideológica diz respeito à orientação editorial e ao público, não à limitação material solicitada.","B":"A densidade temática é uma característica de elaboração; não identifica a restrição física da página.","C":"O público leitor é relevante ao gênero, mas o aspecto tecnológico apontado está no espaço disponível para publicar.","D":"O próprio texto afasta a necessidade de uma moral e distingue exemplaridade de valoração moral.","E":"O espaço limitado da página impõe concisão e interfere diretamente na composição da crônica."},"takeaway":"Quando o comando destaca suporte ou tecnologia, procure condições materiais de produção e circulação do texto.","key":"linguagens:L793","area":"linguagens","year":2025,"number":32,"answer":"E","subject":"Tecnologias da Informação e Comunicação","topic":"Leitura crítica da mídia e circulação da informação","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A escola na prevenção da violência","steps":["O cartaz pergunta por que tratar de violência contra mulheres na escola e apresenta a ação “Maria da Penha vai à escola”.","Os efeitos sobre meninas e meninos justificam envolver a educação na prevenção e no debate sobre violência de gênero.","A finalidade é promover engajamento do setor educacional: B. As referências a pesquisa apoiam a mensagem, mas não são seu objetivo principal."],"alternatives":{"A":"O texto aborda violência contra mulheres de forma mais ampla; não anuncia exclusivamente campanha virtual contra feminicídio.","B":"A pergunta dirigida à escola e a ação citada convidam a educação a participar da luta contra a violência.","C":"Meninas e meninos são mencionados como afetados, sem uma comparação quantitativa ou hierarquia de impacto.","D":"O problema excede a segurança física dentro da escola; a escola é chamada a atuar sobre a violência na sociedade.","E":"A pesquisa serve de apoio e credibilidade, não de finalidade de divulgação científica do setor de segurança."},"takeaway":"Distingua o dado que sustenta uma campanha da ação social que ela pretende provocar.","key":"linguagens:L046","area":"linguagens","year":2025,"number":33,"answer":"B","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ambiguidade e função poética","steps":["O título permite ler “você está sozinho” ou “você não está sozinho”, conforme se incorpora ou não a palavra entre parênteses.","As pessoas em espaços isolados, muitas com telas, dialogam com essa tensão entre isolamento individual e uma experiência coletiva de solidão.","A função poética aparece no trabalho com a forma da mensagem, que permite múltiplas interpretações: C. Função poética não exige verso ou rima."],"alternatives":{"A":"Informar sobre riscos seria uma finalidade referencial; não explica o trabalho formal solicitado pelo comando.","B":"Expressar atitude do emissor se aproxima da função emotiva, sem identificar o recurso expressivo específico da capa.","C":"Os parênteses geram leituras diferentes e articuladas às imagens, evidenciando a elaboração da própria mensagem.","D":"O pronome “você” estabelece interlocução, mas não é ele que explica a função poética pedida.","E":"Voltar-se ao código para explicá-lo caracteriza metalinguagem. Aqui o foco é o jogo de sentidos da mensagem, não uma explicação do código."},"takeaway":"Função poética é atenção à construção da mensagem; metalinguagem é o código explicando o próprio código.","key":"linguagens:L286","area":"linguagens","year":2025,"number":34,"answer":"C","subject":"Funções e figuras de linguagem","topic":"Funções da linguagem","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"“Daí” como organizador da narrativa oral","steps":["A transcrição apresenta pausas, reformulações, retomadas e repetição de “daí” para ligar acontecimentos.","Esse marcador ajuda a manter a continuidade da fala enquanto o narrador organiza a história em tempo real.","A repetição é uma estratégia da linguagem oral: D. Isoladamente, ela não permite diagnosticar escolaridade ou origem regional do falante."],"alternatives":{"A":"Não há mudança demonstrada para se adaptar a um interlocutor específico; a função observada é encadear a narrativa.","B":"Um marcador compartilhado por muitos falantes não permite determinar, sozinho, sua procedência regional.","C":"Repetições e planejamento durante a fala não revelam por si só o nível de escolaridade de alguém.","D":"O marcador ajuda a articular episódios e a sustentar o fluxo da narrativa, estratégia frequente da oralidade.","E":"A repetição não destaca apenas pontos particulares: ela costura sucessivas partes de todo o relato."},"takeaway":"Marcas de oralidade são recursos de organização, não provas automáticas de deficiência linguística.","key":"linguagens:L263","area":"linguagens","year":2025,"number":36,"answer":"D","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Hércules como chave de leitura do trabalhador","steps":["O primeiro texto apresenta o herói mítico e seus doze trabalhos extraordinários; o segundo enumera numerosas ocupações de João Antonio.","O título e a frase final, “pode chamar de Hércules”, convocam explicitamente a referência mitológica para interpretar sua sobrecarga de trabalho.","Essa relação entre textos constitui intertextualidade: A. O segundo não resume os episódios do mito, mas os reelabora no cotidiano social."],"alternatives":{"A":"O título, a multiplicidade de tarefas e o nome final retomam o mito para construir uma leitura social do trabalhador.","B":"As ocupações modernas não sintetizam matar monstros ou capturar animais do mito; há recriação, não resumo.","C":"O vocabulário do segundo texto é sobretudo cotidiano e profissional; a referência intertextual não depende de léxico erudito.","D":"O mito apresenta trabalhos como expiação, mas o cotidiano de João Antonio não é descrito como reparação de crimes.","E":"O primeiro texto usa predominantemente apresentação no presente; o tempo verbal não é a relação central entre os dois."},"takeaway":"Intertextualidade pode deslocar um herói para o cotidiano e produzir crítica social sem copiar sua história.","key":"linguagens:L145","area":"linguagens","year":2025,"number":37,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Descrição depreciativa e crítica moral","steps":["O narrador usa expressões como “tremor lúbrico”, “banhas moles” e “mão repolhuda”, compondo retratos pouco idealizados.","As insinuações das visitas, o interesse nas relações e os risos dos hóspedes dão à cena um tom de malícia e ridicularização.","A descrição sustenta escárnio associado à degradação moral: A. A menção a folhetins não faz a cena aderir ao sentimentalismo deles."],"alternatives":{"A":"O retrato depreciativo das personagens e as insinuações de interesse e hipocrisia constroem uma atmosfera de escárnio moral.","B":"Não se descrevem condições sanitárias do prédio ou do bairro; os detalhes são voltados às personagens e relações.","C":"Os folhetins são uma leitura da personagem, mas o narrador emprega ironia e depreciação, não idealização sentimental.","D":"Há interesses econômicos, porém não se comprova um esquema específico de enriquecimento ilícito como foco descritivo.","E":"A situação das mulheres pode ser discutida, mas baixa escolarização não é a causa estabelecida para o efeito pedido."},"takeaway":"Adjetivos e detalhes corporais revelam o ponto de vista do narrador; procure seu efeito, não apenas o cenário.","key":"linguagens:L455","area":"linguagens","year":2025,"number":40,"answer":"A","subject":"Literatura","topic":"Realismo e Naturalismo — Machado de Assis e outros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Objeto, natureza e continuidade cultural","steps":["O primeiro texto situa o banco em narrativas de origem e em práticas tradicionais transmitidas por gerações.","A imagem apresenta um banco em forma reconhecível de tatu: elementos da fauna recebem função de objeto cultural com valor simbólico.","A articulação entre herança cultural e nova função dos elementos naturais corresponde a B. Não é apenas decoração com grafismos."],"alternatives":{"A":"O texto destaca sacralidade e criação, não domínio humano sobre animais. A leitura de controle não é sustentada.","B":"A forma animal é incorporada ao banco, mantendo uma tradição cultural e atribuindo função ao elemento da fauna.","C":"O tatu continua identificável; os traços do animal não são anulados pela transformação em banco.","D":"Os grafismos existem, mas sozinhos não explicam a relação entre mito, natureza e transmissão cultural construída pelos textos.","E":"A figura remete a um animal reconhecível, não necessariamente a uma criatura fantástica inventada."},"takeaway":"Para ler arte indígena, articule forma, uso, cosmologia e transmissão cultural, sem reduzi-la a decoração.","key":"linguagens:L617","area":"linguagens","year":2025,"number":41,"answer":"B","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Linguagem acessível não é necessariamente coloquial","steps":["O quadro contrapõe construções jurídicas rebuscadas a versões como “Torna-se proibido pagar benefícios vitalícios”.","As traduções mantêm registro padrão, mas trocam vocábulos e estruturas especializadas por formulações mais acessíveis.","O contraste irônico evidencia que o juridiquês pode dificultar uma mensagem explicável em variedade padrão de alcance geral: A."],"alternatives":{"A":"As versões são acessíveis e seguem a norma-padrão, ampliando o público sem reproduzir o jargão especializado.","B":"Não se apresenta uma sequência de versões antigas e atuais para documentar a evolução histórica das leis.","C":"Clareza não implica coloquialidade: as traduções não reproduzem uma conversa cotidiana informal.","D":"O movimento é de afastamento do rebuscamento e latinismos, e não de recuperação de uma variedade erudita.","E":"O jargão técnico é justamente simplificado para leitores não especialistas; não é a variedade de chegada."},"takeaway":"Padrão, formal, claro e técnico são dimensões distintas. Não confunda acessibilidade com informalidade.","key":"linguagens:L264","area":"linguagens","year":2025,"number":42,"answer":"A","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Enumerar benefícios como argumento","steps":["O texto defende a leitura na infância e organiza quatro razões: vínculo emocional, capacidades cognitivas, conhecimento do mundo e imaginação.","Essa lista fornece benefícios concretos para persuadir o leitor a adotar o hábito em casa.","A estratégia central é enumerar razões pertinentes: D. Há outras marcas linguísticas, mas elas não substituem a sustentação argumentativa da lista."],"alternatives":{"A":"A oração com “se” introduz a possível necessidade de motivação; não é a principal condição imposta para ler às crianças.","B":"“Parece que” aparece no início, mas a defesa da leitura não se baseia em relativizar a própria opinião.","C":"A metáfora “laço de amorosidade” contribui para o tom afetivo, mas a lista é a estrutura principal de razões.","D":"A enumeração torna explícitos benefícios que justificam e incentivam o ato de ler para crianças.","E":"A corresponsabilidade aparece em “nossa função”, mas não explica tão diretamente a organização dos argumentos apresentada."},"takeaway":"Vários recursos podem coexistir; escolha aquele que explica de modo mais completo a estratégia pedida.","key":"linguagens:L314","area":"linguagens","year":2025,"number":44,"answer":"D","subject":"Gramática a serviço do sentido","topic":"Sintaxe, pontuação e relações de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Palavra e imagem se complementam","steps":["A ilustração traz mãos segurando água e a palavra árabe “Gufra”, acompanhada de sua explicação verbal.","A frase esclarece que se trata da quantidade de água que pode ser segurada com as mãos, orientando a leitura do desenho.","O texto verbal explica o significado da expressão ilustrada: C. A dificuldade de tradução não equivale a impossibilidade de explicar o conceito."],"alternatives":{"A":"A legenda não oferece uma descrição técnica dos materiais ou do processo de desenho; define uma expressão.","B":"Apresenta-se um sentido específico, e não um conjunto de acepções diferentes do mesmo verbete.","C":"A explicação verbal explicita o significado que a cena das mãos e da água representa visualmente.","D":"Não há lista de palavras equivalentes em várias línguas; há um termo e uma explicação em português.","E":"O texto ajuda a compreender o conceito, em vez de apenas apontar que o leitor teria dificuldade de entendê-lo."},"takeaway":"Sem equivalente de uma única palavra ainda é possível explicar um conceito por uma expressão e uma imagem.","key":"linguagens:L002","area":"linguagens","year":2025,"number":45,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Recursos expressivos e construção de sentidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2025.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
